# pylint: disable-all
__author__ = 'Velocity Support'

import unittest
import sys
import os
import json
import re

sys.path.insert(
    0, os.path.abspath(os.path.join(os.path.dirname(__file__), '../..'))
)

from topology import *

logger.disabled = True


# Full xml has 3 different devices.
# Device1: FSMF 2, Ports: Port 2, Port 1
# Device2: FXED, Ports: Port 2, Port 1
# Device3: FXED 2, Ports: Port 1
# Links: FSMF : Port 2 -> FXED : Port 1, FSMF : Port 1 -> FXED 2 : Port 1


class TopologyTestCase(unittest.TestCase):

    def get_file(self, filename):
        with open(os.path.dirname(__file__) + "/test_tbmls/" + filename, "rb") as f:
            data = f.read()
        return data

    def test_init_topology_tbml(self):
        xml = self.get_file("empty.xml")
        t = Topology(xml)
        new = t.to_tbml()
        self.assertEqual(xml, new)

    def test_get_note_from_topology(self):
        xml = self.get_file("note_in_topo.xml")
        t = Topology(xml)
        self.assertEqual(1, len(t.layer))
        note = t.get_note_by_string("testpool")
        self.assertEqual(t.layer[0], note)
        self.assertEqual(note.color, "GREEN")
        self.assertEqual(note.id, "i4fa8205e-58c4-492b-9689-f816a5e75d54")
        self.assertEqual(note.content, "oam_vm=10.35.177.210\ntestpool=OAMAF1\nreserved_host=5gRobot16."
                                       "ou.nsn-rdnet.net\nbts_name=OAM-SCT-BTS6\nairframe_ip=10.35.189.34")
        note.color = "YELLOW"
        self.assertEqual(note.color, "YELLOW")
        note.id = "1234"
        self.assertEqual(note.id, "1234")
        note.content = "ok"
        self.assertEqual(note.content, "ok")
        self.assertEqual(note.subject, "iddqd")

    def test_topo_get_device_by_regex(self):
        xml = self.get_file("note_in_topo.xml")
        t = Topology(xml)
        regex = ".*5g.*test.*pc.*"
        device = t.get_device_by_regex(regex)
        self.assertEqual(t.resources[0], device)

    def test_parse_tbml_device_properties(self):
        xml = self.get_file("device_properties.xml")
        t = Topology(xml)
        regex = ".*5g.*test.*pc.*"
        device = t.get_device_by_regex(regex)
        self.assertTrue(hasattr(device, "_ipaddress"))

    def test_add_device_as_str(self):
        xml = self.get_file("empty.xml")
        t = Topology(xml)
        d = "asdf"
        r = t.add_device(d)
        self.assertIsNone(r)
        self.assertEqual(xml, t.to_tbml())

    def test_add_device_as_Device(self):
        t = Topology(self.get_file("empty.xml"))
        d = Device(self.get_file("device_fsmf.xml"), "xml")
        self.assertIsInstance(d, Device)
        t.add_device(d)
        self.assertEqual(self.get_file("empty_plus_fsmf.xml"), t.to_tbml())

    def test_delete_device_as_Device(self):
        xml = self.get_file("empty.xml")
        t = Topology(xml)
        d = Device(self.get_file("device_fsmf.xml"), "xml")
        t.add_device(d)
        t.delete_device("FSMF")
        topo = t.to_tbml()
        self.assertEqual(xml, topo)

    def test_delete_device_as_empty(self):
        xml = self.get_file("empty.xml")
        t = Topology(xml)
        self.assertFalse(t.delete_device("Server #1"))
        topo = t.to_tbml()
        self.assertEqual(xml, topo)

    def test_delete_fsmf_from_full(self):
        t = Topology(self.get_file("full.xml"))
        t.delete_device("FSMF 2")
        self.assertEqual(self.get_file("fsmf_deleted.xml"), t.to_tbml())

    def test_delete_fxed_port1_from_full(self):
        t = Topology(self.get_file("full.xml"))
        l = {"from_device": "FXED", "from_port": "Port 1", "to_device": "FSMF 2", "to_port": "Port 2"}
        t.delete_link(l)
        self.assertEqual(self.get_file("fxed_port1_deleted.xml"), t.to_tbml())

    def test_add_device_port_link_to_full(self):
        t = Topology(self.get_file("full.xml"))
        d = Device(self.get_file("device_fsmf.xml"), "xml")
        p = d.create_port({"name": "Port 33", "condition": "[portNumber] = 'OPT2'"})
        # These are usually generated
        p.guid = "1d59d65ae5cd456d8bdba030e9bb2a38"
        p.id = "d44a32c6baa240d6b18f8382308482ab"
        t.add_device(d)
        l = t.create_link({"action": "add", "from_device": "FXED", "from_port": "Port 2",
                           "to_device": "FSMF", "to_port": "Port 33", "condition": "",
                           "type": "RP3", "direction": "bidirectional"})
        l.id = "d870f9e18b614d20999e27cdc63307a3"
        l.name = "30aa25bff7b642769fba9443c2c8c8b4"
        self.assertEqual(self.get_file("full_plus_device_port_link.xml"), t.to_tbml())

    def test_init_empty_tbml(self):
        t = Topology()
        self.assertEqual(self.get_file("empty.xml"), t.to_tbml())

    def test_add_topo_name(self):
        t = Topology(self.get_file("full.xml"))
        t.name = "Markku"
        self.assertIn("<name>Markku</name>", t.to_tbml())

    def test_add_device_to_empty_tbml(self):
        t = Topology()
        d = Device(self.get_file("device_fsmf.xml"), "xml")
        self.assertIsInstance(d, Device)
        t.add_device(d)
        self.assertEqual(self.get_file("empty_plus_fsmf.xml"), t.to_tbml())

    def test_delete_device_from_subtopo_which_is_in_topo(self):
        t = Topology(self.get_file("topo_with_subtopo.xml"))
        t.delete_device("ABIA-267055")
        self.assertEqual(self.get_file("topo_with_subtopo_device_deleted.xml"), t.to_tbml())

    def test_convert_topology_to_subtopology_and_add_topology(self):
        t = Topology(self.get_file("subtopology.xml"))
        subtopo = t.convert_to_subtopology()
        # links = t.links
        subtopo.topology['guid'] = "593884b3117644fc91583639ccf0d102"
        subtopo.topology['id'] = "25fcc7f362d642cdb1afd2ffe3a780ce"
        t_full = Topology(self.get_file("full.xml"))
        t_full.add_subtopology(subtopo)
        self.assertEqual(self.get_file("full_plus_subtopology.xml"), t_full.to_tbml())

    def test_create_cloud_topology(self):
        t = Topology(name="TEST_TOPOLOGY", description="TESTING_THIS")
        # add vm
        vm = VirtualMachine(name="Test VM", min_cpu_cores=2,
                            min_ram_mb=512, min_disk_gb=40, image_name="uuh", cloud_id="CLOUD_ID_HERE")  # or string
        t.add_device(vm)
        vm.guid = "VM_GUID"
        vm.id = "VM_ID"
        vport = VirtualPort(str_type="json", name="VNIC1", vm_id=vm.id)
        vport.id = "VPORT_ID"
        vport.guid = "VPORT_GUID"
        vm.add_port(vport)
        # add vlan
        vlan = Vlan(name="NEW VLAN", vlan_id=1234)  # or vlan_id="1234"
        vlan.id = "VLAN_ID"
        vlan.guid = "VLAN_GUID"
        t.add_device(vlan)
        # add abstract SM
        sm = Device({"name": "SM1", "condition": "template[FSMF]"}, type="json")
        sm.id = "SM_ID"
        sm.guid = "SM_GUID"
        t.add_device(sm)
        # create connection between vlan and sm
        l = t.create_link_by_id(sm.id, vlan.id, type="Virtual", direction="bidirectional")
        l.name = "VIRTUAL_LINK2"
        l.id = "LINK_ID"
        # create public network
        vpn = VirtualPublicNetwork(cloud_id="CLOUD_ID_HERE", name="VIRTUAL_PUBLIC_NETWORK",
                                   ip_version="IPV4", dns_addr="1.1.1.1", network_range="192.168.22.1/24",
                                   dchp_enabled=True, gw_addr="1.2.3.4")
        vpn.id = "VPN_ID"
        vpn.guid = "VPN_GUID"
        t.add_device(vpn)
        # create connection between vpn and vm
        l = t.create_link_by_id(vport.id, vpn.id, type="Virtual", direction="bidirectional")
        l.name = "VIRTUAL_LINK"
        l.id = "LINK_ID"
        self.assertEqual(self.get_file("full_cloud.xml"), t.to_tbml())

    def test_create_link_vlan_device(self):
        t = Topology(name="TEST_TOPOLOGY", description="TESTING_THIS")
        device_data = {
            "name": "FSMF2",
            "condition": "int [4Booking ID] = 259780"
        }
        d = Device(device_data, "json")
        vlan = Vlan(name="TEST_VLAN", vlan_id=4001)
        t.add_resource(d)
        port_data = {
            "name": "Test Port",
            "condition": "any"
        }
        d.create_port(port_data)
        t.add_resource(vlan)
        t.create_link_by_id(vlan.id, d.get_port("Test Port").id, name="Turska")
        self.assertIn(t.links[0].name, "Turska")


if __name__ == '__main__':
    unittest.main()
